import {classify} from './parser.js';
function exportLabel(raw,classification){
 if(classification.kind!=='timed')return raw.trim().toLocaleUpperCase('de-DE');
 const code=raw.trim().match(/[a-zäöü]+$/i)?.[0];
 return code?code.toLocaleUpperCase('de-DE'):'Dienst';
}
function escape(s){return String(s).replace(/\\/g,'\\\\').replace(/\r?\n/g,'\\n').replace(/;/g,'\\;').replace(/,/g,'\\,')}
function fold(s){let line='',bytes=0,out=[];for(const c of s){const size=new TextEncoder().encode(c).length;if(bytes+size>75){out.push(line);line=' ';bytes=1}line+=c;bytes+=size}out.push(line);return out.join('\r\n')}
function hash(s){let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return (h>>>0).toString(16)}
function utc(d){return d.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z')}
export function berlinUTC(date,time){const [y,m,d]=date.split('-').map(Number),[h,min]=time.split(':').map(Number);const guess=Date.UTC(y,m-1,d,h,min);let value=guess;for(let i=0;i<3;i++){const p=Object.fromEntries(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'}).formatToParts(new Date(value)).filter(x=>x.type!=='literal').map(x=>[x.type,+x.value]));const local=Date.UTC(p.year,p.month-1,p.day,p.hour,p.minute,p.second);value+=guess-local}return new Date(value)}
export function createICS(name,entries,duration){const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Dienstplan//Lokaler Kalenderexport//DE','CALSCALE:GREGORIAN','METHOD:PUBLISH',`X-WR-CALNAME:${escape('Dienstplan · '+name)}`,'X-WR-TIMEZONE:Europe/Berlin'];for(const entry of entries){const c=classify(entry.raw);lines.push('BEGIN:VEVENT',`UID:${hash(name+'|'+entry.date+'|'+entry.raw)}-${entry.date}@dienstplan.local`,`DTSTAMP:${utc(new Date())}`);if(c.kind==='timed'){const start=berlinUTC(entry.date,c.time);lines.push(`DTSTART:${utc(start)}`);if(Number(duration)>0)lines.push(`DTEND:${utc(new Date(start.getTime()+Number(duration)*3600000))}`)}else{const end=new Date(entry.date+'T12:00:00Z');end.setUTCDate(end.getUTCDate()+1);lines.push('DTSTART;VALUE=DATE:'+entry.date.replaceAll('-',''),'DTEND;VALUE=DATE:'+end.toISOString().slice(0,10).replaceAll('-',''))}lines.push(`SUMMARY:${escape(exportLabel(entry.raw,c)+' · Casino')}`,`DESCRIPTION:${escape('Originaleintrag: '+entry.raw+'\nZeiten: Europe/Berlin. '+(c.kind==='timed'?(Number(duration)>0?'Endzeit aus gewählter Dauer ('+duration+' Stunden), nicht aus dem PDF.':'Nur Dienstbeginn; der Plan enthält keine Endzeit.'):'Keine Uhrzeit im Plan; als ganztägiger Eintrag exportiert.'))}`,c.kind==='absence'?'TRANSP:TRANSPARENT':'TRANSP:OPAQUE','END:VEVENT')}lines.push('END:VCALENDAR');return lines.map(fold).join('\r\n')+'\r\n'}
